static int xiao_app_sed__parse_subst(char *expr, const char **old_text, const char **new_text) {
    char delim;
    char *p;
    if (!expr || expr[0] != 's' || !expr[1]) return -1;
    delim = expr[1];
    *old_text = expr + 2;
    p = expr + 2;
    while (*p && *p != delim) p++;
    if (!*p) return -1;
    *p++ = 0;
    *new_text = p;
    while (*p && *p != delim) p++;
    if (*p) *p = 0;
    return 0;
}

